    /// <summary>
    ///    Determines whether the specified reason occurs in the table.
    /// </summary>
    /// <param name="_reason">
    ///    The reason code to find.
    /// </param>
    /// <returns>
    ///    true if the reason exists for the given <c>ReasonCodeAccountType</c> table; otherwise, false.
    /// </returns>
    public static boolean checkExist(ReasonCode _reason)
    {
        boolean ret = true;
 
        if (!METExcludedReasonCode::exist(_reason))
        {
            ret = checkFailed(strfmt(METExcludedReasonCode::txtNotExist(), _reason));
        }

        return ret;
    }

    /// <summary>
    ///    Determines whether the specified reason occurs in the table.
    /// </summary>
    /// <param name="_reason">
    ///    The reason code to find.
    /// </param>
    /// <returns>
    ///    true if the reason exists for the given <c>ReasonCodeAccountType</c> table; otherwise, false.
    /// </returns>
    public static boolean exist(ReasonCode _reason)
    {
        boolean found;
 
        found = (select firstonly
                     RecId
                from
                     metExcludedReasonCode
                 where
                     metExcludedReasonCode.Reason == _reason).RecId != 0;

        return found;
    }

    /// <summary>
    ///    Reads the <c>Reason</c> table to find the specified <c>Reason</c>.
    /// </summary>
    /// <param name="_excludedReasonCode">
    ///    The <c>Reason</c> Code to find.
    /// </param>
    /// <param name="_forupdate">
    ///    A Boolean value that determines whether the record should be selected for update; optional.
    /// </param>
    /// <param name="_concurrencyModel">
    ///    A value that is used when the table is not automatically concurrent; optional.
    /// </param>
    /// <returns>
    ///    A <c>Reason</c> table buffer.
    /// </returns>
    /// <remarks>
    ///    This is a public method that is used to find records.
    /// </remarks>
    public static METExcludedReasonCode find(
        ReasonCode          _excludedReasonCode,
        boolean             _forupdate = false,
        ConcurrencyModel    _concurrencyModel = ConcurrencyModel::Auto)
    {
        METExcludedReasonCode excludedReasonCode;

        if (_excludedReasonCode != '')
        {
            excludedReasonCode.selectForUpdate(_forupdate);
            if (_forupdate  && _concurrencyModel != ConcurrencyModel::Auto)
            {
                excludedReasonCode.concurrencyModel(_concurrencyModel);
            }

            select firstonly
                excludedReasonCode
                where
                excludedReasonCode.Reason == _excludedReasonCode;
        }

        return excludedReasonCode;
    }

/// <summary>
/// Returns the label number to use when displaying a message to indicate that the record does not exist.
/// </summary>
/// <returns>
/// A string indicating the label number to use.
/// </returns>
public static TxtNotExist txtNotExist()
{
    return "@SYS114722";
}

    /// <summary>
    /// CB175_SalesConfirmation
    /// METExcludedreason code Modified field
    /// </summary>
    /// <param name = "_fieldId">fieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        if (_fieldId == fieldNum(METExcludedReasonCode, Reason))
        {
            this.Description = ReasonTable::find(this.Reason).Description;
        }
    }
